from typing import List

class Solution:
    def maximumNumberOfStringPairs(self, words: List[str]) -> int:
        seen = set()
        count = 0
        for w in words:
            rev = w[::-1]
            if rev in seen:
                count += 1
            else:
                seen.add(w)
        return count
